# -*- coding: utf-8 -*-
"""Collect the real comparison-suite CSV generated by the fair benchmark runner."""

from __future__ import annotations

import csv
import json
from pathlib import Path

ORDER = [
    "KNN",
    "Gaussian NB",
    "LDA",
    "SVM",
    "Logistic Regression",
    "Random Forest",
    "TFN",
    "MLP",
    "CNN",
    "LSTM",
    "PhysioFormer-OS",
]


def model_type(name: str) -> str:
    if name in {"KNN", "Gaussian NB", "LDA", "SVM", "Logistic Regression", "Random Forest"}:
        return "Classical ML"
    return "Deep Learning"


def main() -> None:
    base = Path(__file__).resolve().parent / "results" / "fair_suite"
    outdir = Path(__file__).resolve().parent / "results"
    outdir.mkdir(parents=True, exist_ok=True)
    outpath = outdir / "comparison_suite.csv"
    rows = []
    for name in ORDER:
        summ_path = base / name.replace(" ", "_") / "summary.json"
        if not summ_path.exists():
            raise FileNotFoundError(f"Missing model summary: {summ_path}")
        summary = json.loads(summ_path.read_text(encoding="utf-8"))
        rows.append(
            (
                name,
                round(float(summary["accuracy"]), 3),
                round(float(summary["macro_f1"]), 3),
                round(float(summary["auc_ovr"]), 3),
                model_type(name),
            )
        )
    with outpath.open("w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["method", "accuracy", "macro_f1", "auc_ovr", "type"])
        writer.writerows(rows)
    print(f"[saved] {outpath}")


if __name__ == "__main__":
    main()
